/**
 * The published rule set. Every number the engine produces points at one or
 * more of these rules, and the same rules apply to every user. Nothing here is
 * generated by an AI model at run time.
 *
 * `verified` records whether a person has checked the citation against the
 * current ATO page for the tax year. Unverified rules are shown with a notice.
 */

export interface Rule {
  id: string;
  title: string;
  /** Plain-English statement of the rule, shown to the user. */
  statement: string;
  citation: { label: string; url: string };
  verified: boolean;
}

const r = (rule: Rule) => rule;

