export type RuleId = keyof typeof RULES;

/** Year-specific parameters. Add a new entry each year after checking myTax. */
export interface TaxYearParams {
  /** e.g. 2026 means the year ended 30 June 2026 (FY2025-26). */
  year: number;
  start: string;
  end: string;
  cgtDiscountRate: number;
  fitoNoCalcThreshold: number;
}

export const TAX_YEARS: Record<number, TaxYearParams> = {
  2025: { year: 2025, start: '2024-07-01', end: '2025-06-30', cgtDiscountRate: 0.5, fitoNoCalcThreshold: 1000 },
  2026: { year: 2026, start: '2025-07-01', end: '2026-06-30', cgtDiscountRate: 0.5, fitoNoCalcThreshold: 1000 },
};

export function taxYearParams(year: number): TaxYearParams {
  const p = TAX_YEARS[year];
  if (!p) throw new Error(`Tax year ${year} is not supported yet. Supported: ${Object.keys(TAX_YEARS).join(', ')}`);
  return p;
}
